class MapScreen extends StatefulWidget{const MapScreen({super.key});@override State<MapScreen> createState()=>_MapScreenState();}
class _MapScreenState extends State<MapScreen> with SingleTickerProviderStateMixin{late final AnimationController anim=AnimationController(vsync:this,duration:const Duration(seconds:16))..repeat();@override void dispose(){anim.dispose();super.dispose();}@override Widget build(BuildContext context){final s=context.watch<AppState>();return Stack(children:[Positioned.fill(child:InteractiveViewer(minScale:.6,maxScale:4,boundaryMargin:const EdgeInsets.all(200),child:SizedBox(width:1000,height:700,child:AnimatedBuilder(animation:anim,builder:(c,_) => CustomPaint(painter:_WorldPainter(s.activeVehicles,anim.value))))),),Positioned(left:12,right:12,top:12,child:Row(children:[_chip(Icons.notifications_none,'2'),const Spacer(),_chip(Icons.ac_unit,'Musim dingin • sisa 26m 25s')])),Positioned(left:12,right:12,bottom:12,child:Column(children:[Container(padding:const EdgeInsets.all(13),decoration:BoxDecoration(color:AppColors.surface,borderRadius:BorderRadius.circular(15),border:Border.all(color:AppColors.border)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('TARGET BERIKUTNYA • 2 DARI 8',style:TextStyle(color:AppColors.emerald,fontSize:9,fontWeight:FontWeight.w900)),SizedBox(height:7),Text('Buy a second vehicle • 1 / 2',style:TextStyle(fontWeight:FontWeight.w800)),SizedBox(height:8),LinearProgressIndicator(value:.5,color:AppColors.emerald,backgroundColor:AppColors.border)])),const SizedBox(height:10),Row(children:[_chip(Icons.sports_esports,'Mengemudi'),const SizedBox(width:7),_chip(Icons.music_note,'Musik'),const Spacer(),_chip(Icons.emoji_events,'3')])]))]);}}
Widget _chip(IconData i,String t)=>Container(padding:const EdgeInsets.symmetric(horizontal:11,vertical:10),decoration:BoxDecoration(color:AppColors.surface,borderRadius:BorderRadius.circular(13),border:Border.all(color:AppColors.border)),child:Row(mainAxisSize:MainAxisSize.min,children:[Icon(i,size:16,color:AppColors.emerald),const SizedBox(width:6),Text(t,style:const TextStyle(fontSize:9,fontWeight:FontWeight.w800))]));
class _WorldPainter extends CustomPainter{_WorldPainter(this.active,this.progress);final int active;final double progress;@override void paint(Canvas c,Size s){c.drawRect(Offset.zero&s,Paint()..color=AppColors.background);final land=Paint()..color=const Color(0xFF111D24);final shapes=[[.04,.16,.26,.40],[.22,.48,.34,.86],[.42,.15,.62,.39],[.44,.40,.64,.83],[.64,.12,.96,.51],[.76,.64,.94,.91]];for(final a in shapes){c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTRB(a[0]*s.width,a[1]*s.height,a[2]*s.width,a[3]*s.height),const Radius.circular(70)),land);}final cities=CityCatalog.allCities;final pts=<Offset>[];for(final city in cities){pts.add(Offset(city.mapX*s.width,city.mapY*s.height));}final line=Paint()..color=const Color(0xFF1E2E38)..strokeWidth=2;for(var i=0;i<pts.length-1;i++){c.drawLine(pts[i],pts[i+1],line);}final route=Paint()..color=AppColors.emerald..strokeWidth=3;c.drawLine(pts.first,pts[1],route);final p=Offset(pts.first.dx+(pts[1].dx-pts.first.dx)*progress,pts.first.dy+(pts[1].dy-pts.first.dy)*progress);c.drawCircle(p,7,Paint()..color=AppColors.emerald);for(var i=0;i<cities.length;i++){c.drawCircle(pts[i],cities[i].name=='Jakarta'?9:5,Paint()..color=cities[i].name=='Jakarta'?AppColors.gold:AppColors.textSecondary);final tp=TextPainter(text:TextSpan(text:cities[i].name,style:const TextStyle(color:AppColors.textSecondary,fontSize:11)),textDirection:TextDirection.ltr)..layout();tp.paint(c,pts[i].translate(8,-5));}final extra=['Sukabumi','Bandung','Blitar','Jambi','Pontianak','Singapore','George Town','Bangkok','Can Tho','Guangzhou','Shanghai','Beijing','Seoul','Tokyo','Chennai','Kolkata','Karachi','Dubai','Rotterdam','Los Angeles','Sydney'];for(var i=0;i<extra.length;i++){final p=Offset((.12+(i%7)*.12)*s.width,(.25+(i%5)*.12)*s.height);c.drawCircle(p,3,Paint()..color=AppColors.textSecondary);}}@override bool shouldRepaint(covariant _WorldPainter old)=>old.progress!=progress||old.active!=active;}